126	    }
127	
128	    public List<Pet> getPets() {
129	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
130	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
131	        return Collections.unmodifiableList(sortedPets);
132	    }
133	
134	    public void setPets(List<Pet> pets) {
135	        this.pets = new HashSet<>(pets);
136	    }
