17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
105	        if (normalizedTelephone == null) {
106	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
107	        }
108	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
109	            return new ResponseEntity<>(HttpStatus.CONFLICT);
110	        }
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        owner.setTelephone(normalizedTelephone);
114	        if (owner.getRegistrationDate() == null) {
115	            owner.setRegistrationDate(LocalDate.now());
116	        }
117	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
118	        this.clinicService.saveOwner(owner);
119	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
120	        headers.setLocation(UriComponentsBuilder.newInstance()
121	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
122	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
128	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
129	        if (currentOwner == null) {
130	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
131	        }
132	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
133	        if (normalizedTelephone == null) {
134	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
135	        }
136	        currentOwner.setAddress(ownerFieldsDto.getAddress());
137	        currentOwner.setCity(ownerFieldsDto.getCity());
138	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
139	        currentOwner.setLastName(ownerFieldsDto.getLastName());
140	        currentOwner.setTelephone(normalizedTelephone);
141	        currentOwner.setEmail(ownerFieldsDto.getEmail());
142	        this.clinicService.saveOwner(currentOwner);
143	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Transactional
148	    @Override
149	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
150	        Owner owner = this.clinicService.findOwnerById(ownerId);
151	        if (owner == null) {
152	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
153	        }
154	        this.clinicService.deleteOwner(owner);
155	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
161	        Owner owner = this.clinicService.findOwnerById(ownerId);
162	        if (owner == null) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        HttpHeaders headers = new HttpHeaders();
166	        Pet pet = petMapper.toPet(petFieldsDto);
167	        owner.setId(ownerId);
168	        pet.setOwner(owner);
169	        pet.getType().setName(null);
170	        this.clinicService.savePet(pet);
171	        PetDto petDto = petMapper.toPetDto(pet);
172	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
173	            .buildAndExpand(pet.getId()).toUri());
174	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
180	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
181	        if (currentOwner != null) {
182	            Pet currentPet = this.clinicService.findPetById(petId);
183	            if (currentPet != null) {
184	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
185	                currentPet.setName(petFieldsDto.getName());
186	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
187	                this.clinicService.savePet(currentPet);
188	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
189	            }
190	        }
191	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
192	    }
193	
194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Override
196	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
197	        HttpHeaders headers = new HttpHeaders();
198	        Visit visit = visitMapper.toVisit(visitFieldsDto);
199	        Pet pet = new Pet();
200	        pet.setId(petId);
201	        visit.setPet(pet);
202	        this.clinicService.saveVisit(visit);
203	        VisitDto visitDto = visitMapper.toVisitDto(visit);
204	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
